/* PLAZA — ОБЩИЕ ЭФФЕКТЫ: менять значения только здесь.
   Стеклянный контейнер: класс glass-panel на блоке «Группа».
   Иконка внутри него: класс glass-icon.
   Фотографии Gutenberg подключаются автоматически.
   Для другой обёртки фотографии: класс photo-frame.
   Для исключения фотографии: класс no-photo-effect на блоке. */
:root {
  /* Glass material tokens live in shared/tokens.css. */





  --photo-hover-scale: 1.035;
  --photo-hover-brightness: 1.1;
  --photo-hover-saturation: 1;
  --photo-effect-duration: 1s;
  --photo-rest-saturation: 1;
}

/* Стекло — существующий контейнер и все будущие glass-panel */
body :is(.hero-glass, .glass-panel) {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}
body :is(.plaza-icon-motion, .hero-glass, .glass-panel, .facts > div, .visit-grid > article) :is(.glass-icon, .plaza-icon, .wp-block-image.icon) {
  display: inline-block;
  transform-origin: center;
  transition: transform .35s ease;
}
@media (hover: hover) and (pointer: fine) {
  body :is(.plaza-icon-motion, .hero-glass, .glass-panel, .facts > div, .visit-grid > article):is(:hover,:focus-within) :is(.glass-icon, .plaza-icon, .wp-block-image.icon) {
    transform: var(--plaza-icon-transform);
  }
}

/* Все фотографии контента; логотипы и иконки не затрагиваются */
body main :is(.photo-frame, .wp-block-image):where(:not(.no-photo-effect):not(.icon):not(.glass-icon)) {
  overflow: hidden;
}
body main :is(.photo-frame, .wp-block-image):where(:not(.no-photo-effect):not(.icon):not(.glass-icon)) img {
  transform: scale(1);
  filter: none;
  transition: transform var(--photo-effect-duration) ease, filter var(--photo-effect-duration) ease;
}
@media (hover: hover) and (pointer: fine) {
  body main :is(.photo-frame, .wp-block-image):where(:not(.no-photo-effect):not(.icon):not(.glass-icon)):hover img,
  body main .card:is(:hover,:focus-within) .photo-frame img {
    transform: scale(var(--photo-hover-scale));
    filter: brightness(var(--photo-hover-brightness));
  }
}
@media (prefers-reduced-motion: reduce) {
  body :is(.plaza-icon-motion, .hero-glass, .glass-panel, .facts > div, .visit-grid > article) :is(.glass-icon, .plaza-icon, .wp-block-image.icon),
  body main :is(.photo-frame, .wp-block-image):where(:not(.no-photo-effect):not(.icon):not(.glass-icon)):hover img {
    transform: none;
  }
}

/* PLAZA — общие стили кнопок. Тип 1: подсветка снизу и живые искры.
   Тип 2: стекло, однократный перелив и живые частицы (вариант 15).
   Gutenberg: button-type-1 / button-type-2. */
:root { --button-radius:4px; --button-metal:#b2945f; }
body :is(.button, .wp-block-button:is(.plaza-button,.button-type-1,.button-type-2) .wp-block-button__link) {
  position:relative;isolation:isolate;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;
  border:1px solid var(--button-metal);border-radius:var(--button-radius);text-decoration:none;
  font-family:Montserrat,Arial,sans-serif;
  transition:background-color .35s ease,color .3s ease,box-shadow .35s ease,transform .3s ease;
}
body :is(.button, .wp-block-button:is(.plaza-button,.button-type-1,.button-type-2) .wp-block-button__link)::before {content:"";position:absolute;inset:0;z-index:-1;border-radius:inherit;pointer-events:none;opacity:0;transition:opacity .35s ease;}
body :is(.button, .wp-block-button:is(.plaza-button,.button-type-1,.button-type-2) .wp-block-button__link)::after {content:none;}
body :is(.button:not(.button-outline), .wp-block-button.plaza-button:not(.plaza-outline) .wp-block-button__link, .wp-block-button.button-type-1 .wp-block-button__link) {
